-- Transactional outbox (no broker). Placing an order writes an OrderPlaced row here in the same
-- transaction as the order, so the event exists if and only if the order does. An in-process relay
-- polls the unsent rows (SELECT ... FOR UPDATE SKIP LOCKED), delivers each one at least once and sets
-- sent_at. A failed delivery bumps attempts and pushes next_attempt_at back (bounded retries with
-- backoff); a row that reaches the relay's max attempts stays unsent for an operator to look at.
--
-- id is the event id, generated by the writer; consumers deduplicate on it. payload is the event body
-- as JSON. Only backend-java (multitier) writes and relays these rows today (a Java-only worked
-- example); the other backends read the same schema and leave both tables empty.
--
-- Additive only: two new tables that previous app versions never read or write -- rollback-safe by
-- construction.
CREATE TABLE outbox (
  id UUID PRIMARY KEY,
  aggregate_type VARCHAR(100) NOT NULL,
  aggregate_id VARCHAR(255) NOT NULL,
  event_type VARCHAR(100) NOT NULL,
  payload JSONB NOT NULL,
  created_at TIMESTAMPTZ NOT NULL,
  sent_at TIMESTAMPTZ,
  attempts INTEGER NOT NULL DEFAULT 0,
  next_attempt_at TIMESTAMPTZ NOT NULL,
  last_error TEXT
);

-- The relay's poll: unsent rows, oldest first. Partial, so sent rows (the vast majority) cost nothing.
CREATE INDEX idx_outbox_unsent ON outbox (created_at) WHERE sent_at IS NULL;

-- The OrderPlaced consumer: one audit row per event. event_id is the primary key, so a redelivered
-- event is a no-op insert (ON CONFLICT DO NOTHING) -- that is what makes at-least-once delivery safe.
-- No foreign key to orders: the audit trail outlives the order row, and the consumer must not depend
-- on the producer's tables.
CREATE TABLE order_placed_audit (
  event_id UUID PRIMARY KEY,
  order_number VARCHAR(255) NOT NULL,
  sku VARCHAR(255) NOT NULL,
  quantity INTEGER NOT NULL,
  total_price NUMERIC(10,2) NOT NULL,
  placed_at TIMESTAMPTZ NOT NULL,
  recorded_at TIMESTAMPTZ NOT NULL
);
